<?php use App\Support\View; ?><main id="conteudo" class="public-page"><header><h1><?=View::e($tournament['name'])?></h1><p><?=View::e($tournament['description'])?></p></header><section><h2>Proximos jogos</h2><?php foreach(array_slice($data['matches'],0,6)as$m):?><p><?=View::e($m['home_name'])?> x <?=View::e($m['away_name'])?> · <?=View::e((string)$m['scheduled_at'])?></p><?php endforeach;?></section><section><h2>Classificacao</h2><?php foreach(array_slice($data['standings'],0,4)as$r):?><p><?=$r['position']?>. <?=View::e($r['team_name'])?> · <?=$r['points']?> pts</p><?php endforeach;?></section><section><h2>Noticias</h2><?php foreach($data['news']as$n):?><article><h3><?=View::e($n['title'])?></h3><p><?=View::e((string)$n['summary'])?></p></article><?php endforeach;?></section></main>
